scripts.温谦对话.txt:
// 和温谦对话

	Say("温谦：今年的年成不错，鱼米满舱，下半年过日子不用愁了！", 0);
	Return;

scripts.紫荆对话.txt:
// 和紫荆对话

	Say("紫荆：唉，我们家那口子整天只知道喝酒，也不出船到湖里转转，真是气死我了！", 0);
	Return;

scripts.莲姑对话.txt:
// 和莲姑对话

	Say("莲姑：人人都说京城好，怎比我洞庭鱼米香？不交皇粮不赋税，老百姓的小天堂！", 0);
	Return;

