scripts.张琳心对话.txt:
// 张琳心的同伴对话

	If ($Event == 540) @Event540;
	If ($Event == 550) @Event550;
	Return;
	
@Event540:	
	Say("张琳心：碧波万顷，波光凛凛，这久别的南国景致真让人感到亲切啊！", 21);
	Say("独孤剑：琳儿，累了吧？我们到茶馆去喝口茶，休息一会，好吗？", 2);
	Say("张琳心：好！", 21);
	Return;
	
@Event550:
	Say("张琳心：我也觉得那茶馆老板有点古怪，我们去问问他吧。", 21);
	Return;

scripts.王老五对话.txt:
// 和王老五对话（支线）

	If ($Saychake == 1) @Talk1;
	If ($Saychake == 2) @Talk2;
	If ($Saychake == 3) @Talk6;
	
	Say("王老五：你，你是谁？");
	Say("独孤剑：老伯，我打听一下天王帮的……", 1);
	Say("王老五：天王帮？……我不知道，不知道！");
	Return;
	
@Talk1:
	Say("独孤剑：你便是王老五？", 1);
	Say("王老五：……", 0);
	Say("独孤剑：你可知道……", 1);
	Say("王老五：求求你，饶了我吧，饶了我吧！", 0);
	Say("独孤剑：这……", 8);
	Say("王老五：我千不该、万不该，不该坏了天王的规矩，私下里去捞了那些沉船的宝贝……求求兄弟们看在我年纪一大把，就放过我吧！", 0);
	Say("独孤剑：原来你私自打捞了沉没的商船……", 1);
	Say("王老五：我知道这是归大伙的……我是一时糊涂，现在我全交出来。求你还给周旱大哥，给小的求个情。", 0);
	Say("王老五交出一千两银子。");
	AddMoney(1000);
	Assign($NoEnd,1);
	AddGoods("Goods413_另一只护腕.ini");
	Assign($Saychake, 2);
	Return;
	
@Talk2:
	Say("王老五：求求兄弟，帮我向周旱大哥求求情。", 0);
	Return;
	
@Talk6:
	If ($Talkcaocao == 1) @Talk3;
	If ($Talkcaocao == 2) @Talk4;

@Talk3:
	If ($Talkwlw == 1) @Talk5;
	
	Say("王老五：兄弟你……");
	Say("独孤剑：王老伯，周旱大哥不会在追究此事了，这些银子是周大哥送给您的！", 2);
	Say("王老五：啊……这如何使得，真是羞煞我了。这点就够了，够了！");
	Say("王老五收下五十两银子。");
	AddMoney(-50);
	Assign($NoEnd,0);
	Assign($Talkwlw, 1);
	Return;
	
@Talk4:
	If ($Talkwlw == 1) @Talk5;
	
	Say("王老五：兄弟你……");
	Say("独孤剑：王老伯，周旱大哥不会在追究此事了。你捞起的这些东西乃是岛上一位兄弟的失物，我们还要多谢您。", 2);
	Say("王老五：这位兄弟……说来实在惭愧，这里还有些银子，我全都交给你。打今儿起，我踏踏实实做人，再也不起这样的心眼了。");
	Say("得到白银三千两");
	AddMoney(3000);
	Assign($NoEnd,0);
	Assign($Talkwlw, 1);
	Return;

@Talk5:
	Say("王老五：打今儿起，我踏踏实实做人，再也不起歪心眼了。");
	Return;

scripts.纪小妹对话.txt:
